from functools import wraps


def retry(max_attempts, exceptions=(Exception,)):
    if max_attempts <= 0:
        raise ValueError("max_attempts must be a positive integer")

    # Normalize exceptions to a tuple of classes
    if isinstance(exceptions, type):
        exceptions = (exceptions,)
    elif not isinstance(exceptions, (tuple, list)):
        raise TypeError("exceptions must be a single exception class or a tuple/list of classes")

    def decorate(fn):
        @wraps(fn)
        def wrapped(*args, **kwargs):
            attempts = 0
            while True:
                attempts += 1
                try:
                    return fn(*args, **kwargs)
                except exceptions as exc:
                    if attempts >= max_attempts:
                        raise
                    # Non-matching exceptions are not caught here, so they propagate immediately
        return wrapped
    return decorate
