        if (!min_deque.empty() && min_deque.front() == idx) {
            min_deque.pop_front();
        }
        if (!max_deque.empty() && max_deque.front() == idx) {
            max_deque.pop_front();
        }
    };

    add_to_deques(0);
    for (int i = 1; i < k; ++i) {
        add_to_deques(i);
    }

    int mn = a[min_deque.front()];
    int mx = a[max_deque.front()];

    for (int left = 0; left + k < n; ++left) {
        if (left > 0) {
            remove_from_deques(left - 1);
