using namespace std;

const int64_t MOD = 1000000007;

struct AffineTag {
    int64_t mul;
    int64_t add;

    AffineTag() : mul(1), add(0) {}

    AffineTag(int64_t m, int64_t a) : mul(m), add(a) {}

    void apply(int64_t v) const {
        v = (v * mul + add) % MOD;
        if (v < 0) v += MOD;
        v %= MOD;
        return v;
    }

    void compose(const AffineTag& other) const {
        mul = (mul * other.mul) % MOD;
        add = (add * other.mul + other.add) % MOD;
        if (add < 0) add += MOD;
        add %= MOD;
    }
};

class LazySegmentTree {
private:
    int n;
    vector<int64_t> tree;
    vector<AffineTag> lazy;

    int64_t normalize(int64_t x) {
        x %= MOD;
        if (x < 0) x += MOD;
        return x;
    }

    void push(int node, int left, int right) {
        if (lazy[node].mul == 1 && lazy[node].add == 0) return;

        int mid = (left + right) / 2;
        int leftChild = 2 * node + 1;
        int rightChild = 2 * node + 2;

        if (lazy[node].mul != 1 || lazy[node].add != 0) {
            lazy[leftChild].compose(lazy[node]);
            lazy[rightChild].compose(lazy[node]);

            tree[leftChild] = normalize(tree[leftChild] * lazy[node].mul % MOD + lazy[node].add % MOD);
            tree[rightChild] = normalize(tree[rightChild] * lazy[node].mul % MOD + lazy[node].add % MOD);
        }

        lazy[node] = AffineTag();
    }

    void build(int node, int left, int right, const vector<int64_t>& arr) {
        if (left == right) {
            tree[node] = normalize(arr[left]);
            lazy[node] = AffineTag();
            return;
        }

        int mid = (left + right) / 2;
        int leftChild = 2 * node + 1;
        int rightChild = 2 * node + 2;

        build(leftChild, left, mid, arr);
        build(rightChild, mid + 1, right, arr);

        tree[node] = normalize(tree[leftChild] + tree[rightChild]);
        lazy[node] = AffineTag();
    }

    void updateRange(int node, int left, int right, int l, int r, const AffineTag& tag) {
        if (l <= left && right <= r) {
            lazy[node].compose(tag);
            tree[node] = normalize(tree[node] * tag.mul % MOD + tag.add % MOD);
            return;
        }

        push(node, left, right);

        int mid = (left + right) / 2;
        int leftChild = 2 * node + 1;
        int rightChild = 2 * node + 2;

        if (l <= mid) {
            updateRange(leftChild, left, mid, l, r, tag);
        }
        if (r > mid) {
            updateRange(rightChild, mid + 1, right, l, r, tag);
        }

        tree[node] = normalize(tree[leftChild] + tree[rightChild]);
    }

    int64_t queryRange(int node, int left, int right, int l, int r) {
        if (l <= left && right <= r) {
            return tree[node];
        }

        push(node, left, right);

        int mid = (left + right) / 2;
        int leftChild = 2 * node + 1;
        int rightChild = 2 * node + 2;

        int64_t res = 0;
        if (l <= mid) {
            res = normalize(res + queryRange(leftChild, left, mid, l, r));
        }
        if (r > mid) {
            res = normalize(res + queryRange(rightChild, mid + 1, right, l, r));
        }
        return res;
    }

public:
    LazySegmentTree(const vector<int64_t>& arr) : n(arr.size()) {
        tree.resize(4 * n);
        lazy.resize(4 * n);
        build(0, 0, n - 1, arr);
    }

    void rangeAdd(int l, int r, int64_t x) {
        AffineTag tag(x, 0);
        updateRange(0, 0, n - 1, l, r, tag);
    }

    void rangeMul(int l, int r, int64_t x) {
        AffineTag tag(x, 0);
        updateRange(0, 0, n - 1, l, r, tag);
    }

    int64_t rangeSum(int l, int r) {
        return queryRange(0, 0, n - 1, l, r);
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    cin >> n >> q;

    vector<int64_t> arr(n);
    for (int i = 0; i < n; ++i) {
        cin >> arr[i];
    }

    LazySegmentTree segTree(arr);

    for (int i = 0; i < q; ++i) {
        string op;
