    SegmentTree(int _n) : n(_n) {
        tree.assign(4 * n, 0);
        lazy_mul.assign(4 * n, 1);
        lazy_add.assign(4 * n, 0);
    }

    void build(const vector<long long>& arr, int node, int l, int r) {
        if (l == r) {
            tree[node] = arr[l] % MOD;
            if (tree[node] < 0) tree[node] += MOD;
            return;
        }
        int mid = (l + r) / 2;
        build(arr, 2 * node, l, mid);
        build(arr, 2 * node + 1, mid + 1, r);
        tree[node] = (tree[2 * node] + tree[2 * node + 1]) % MOD;
    }

    void apply(int node, long long mul, long long add) {
        tree[node] = (tree[node] * mul + add) % MOD;
        if (tree[node] < 0) tree[node] += MOD;
